fragment TokenBasicInfoParts on Token {
  id
  address
  chain
  decimals
  name
  standard
  symbol
  isBridged
  bridgedWithdrawalInfo {
    chain
    provider
    url
    __typename
  }
  __typename
}

fragment TokenFeeDataParts on Token {
  feeData {
    buyFeeBps
    sellFeeBps
    __typename
  }
  __typename
}

fragment TokenProtectionInfoParts on Token {
  protectionInfo {
    result
    attackTypes
    blockaidFees {
      buy
      sell
      transfer
      __typename
    }
    __typename
  }
  __typename
}"}

